            ex.extract(name_v_out, v_cache);
            new_kv_cache.emplace_back(std::move(k_cache), std::move(v_cache));
        }

        ncnn::Mat logits;
        ex.extract("out0", logits);
        return {std::move(logits), std::move(new_kv_cache)};
    }

