148	        if (!cfg.do_sample) {
149	            return argmax1d(logits);
150	        }
151	
152	        std::vector<float> probs(logits.w);
153	        const float* p = logits;
154	        for (int i = 0; i < logits.w; ++i) {
155	            probs[i] = p[i];
156	        }
