198	
199	        float cum = 0.f;
200	        size_t cutoff = v.size();
201	        for (size_t i = 0; i < v.size(); ++i) {
202	            cum += v[i].first;
203	            if (cum >= p) {
204	                cutoff = i + 1;
205	                break;
206	            }
